package com.microboxlabs.miot.teltonika.inputs;

import com.microboxlabs.miot.teltonika.mapping.TeltonikaIo;
import com.microboxlabs.miot.teltonika.protocol.AvlRecord;
import com.microboxlabs.miot.teltonika.protocol.IoElement;
import java.util.HashMap;
import java.util.Map;

/**
 * The inputs one record reports, by canonical name, whatever the brand: {@code din1}..{@code din4}
 * as booleans and {@code ain1}, {@code ain2} in volts. {@code trigger} is the input that generated the
 * record, when the device says so (a Teltonika record generated by DIN1 carries event ID 1).
 */
public record InputReading(Map<String, Boolean> digital, Map<String, Double> analog, String trigger) {

    public static final InputReading NONE = new InputReading(Map.of(), Map.of(), null);

    public InputReading {
        digital = Map.copyOf(digital);
        analog = Map.copyOf(analog);
    }

    public boolean isEmpty() {
        return digital.isEmpty() && analog.isEmpty();
    }

    /** Teltonika I/O: DIN1..DIN3 (IDs 1-3), DIN4 (ID 4, larger models) and AIN1/AIN2 (IDs 9, 10, mV). */
    public static InputReading of(AvlRecord avl) {
        Map<String, Boolean> digital = new HashMap<>();
        digit(avl, TeltonikaIo.DIGITAL_INPUT_1, "din1", digital);
        digit(avl, TeltonikaIo.DIGITAL_INPUT_2, "din2", digital);
        digit(avl, TeltonikaIo.DIGITAL_INPUT_3, "din3", digital);
        digit(avl, TeltonikaIo.DIGITAL_INPUT_4, "din4", digital);
        Map<String, Double> analog = new HashMap<>();
        volts(avl, TeltonikaIo.ANALOG_INPUT_1, "ain1", analog);
        volts(avl, TeltonikaIo.ANALOG_INPUT_2, "ain2", analog);
        String trigger = switch (avl.eventIoId()) {
            case TeltonikaIo.DIGITAL_INPUT_1 -> "din1";
            case TeltonikaIo.DIGITAL_INPUT_2 -> "din2";
            case TeltonikaIo.DIGITAL_INPUT_3 -> "din3";
            case TeltonikaIo.DIGITAL_INPUT_4 -> "din4";
            case TeltonikaIo.ANALOG_INPUT_1 -> "ain1";
            case TeltonikaIo.ANALOG_INPUT_2 -> "ain2";
            default -> null;
        };
        return new InputReading(digital, analog, trigger);
    }

    private static void digit(AvlRecord avl, int id, String name, Map<String, Boolean> out) {
        IoElement e = avl.ioElement(id);
        if (e != null) {
            out.put(name, e.unsigned() == 1);
        }
    }

    private static void volts(AvlRecord avl, int id, String name, Map<String, Double> out) {
        IoElement e = avl.ioElement(id);
        if (e != null) {
            out.put(name, e.unsigned() / 1000d);
        }
    }
}
